parameters.text:
=Evaluate the job fit for this candidate.

Job Details:
Title: {{ $json.job.title }}
Company: {{ $json.job.company }}
Salary: {{ $json.job.salary }}
Location: {{ $json.job.location }}
Description: {{ $json.job.description }}
Required Skills: {{ $json.job.skills }}
Required Experience: {{ $json.job.requiredExperience }}

Candidate Profile:
Skills: {{ $json.profile.skills }}
Years of Experience: {{ $json.profile.yearsOfExperience }}
Salary Range: {{ $json.profile.minSalary }}-{{ $json.profile.maxSalary }}
Seniority: {{ $json.profile.seniority }}
Industry: {{ $json.profile.industry }}

CRITICAL EXPERIENCE MATCHING RULES:
- This candidate has EXACTLY {{ $json.profile.yearsOfExperience }} years of experience
- For freshers (0 years): ONLY match entry-level, junior, trainee, or intern roles. Reject roles requiring 1+ years
- For 1 year experience: Match junior roles and some entry-level positions requiring up to 1 year
- For 2+ years: Match mid-level roles appropriate to their experience
- Heavily penalize mismatches: a fresher matched to a senior role should score below 30
- Prioritize learning opportunities, mentorship, and growth potential for freshers
- Consider if the role explicitly welcomes fresh graduates or career starters

Provide a fit score from 0-100 and a brief explanation. Format your response as:
Score: [number]
Explanation: [text]

parameters.jsCode:
const aiOutput = $json.output;
const scoreMatch = aiOutput.match(/Score:\s*(\d+)/i);
const score = scoreMatch ? parseInt(scoreMatch[1]) : 0;

const explanationMatch = aiOutput.match(/Explanation:\s*(.+)/is);
const explanation = explanationMatch ? explanationMatch[1].trim() : aiOutput;

const job = $("Combine Profile with Jobs").item.json.job;
const profile = $("Combine Profile with Jobs").item.json.profile;

return {
  json: {
    jobId: job.id,
    title: job.title,
    company: job.company,
    salary: job.salary,
    location: job.location,
    url: job.url,
    requiredExperience: job.requiredExperience,
    candidateExperience: profile.yearsOfExperience,
    fitScore: score,
    explanation: explanation
  }
};

const jobs = $json.jobs;
const candidateExp = jobs[0]?.candidateExperience ?? 0;
const expLabel = candidateExp === 0 ? "Fresher" : `${candidateExp} year${candidateExp > 1 ? "s" : ""} experience`;

let html = `
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    h1 { color: #2c3e50; }
    .exp-badge { background: #3498db; color: white; padding: 8px 15px; border-radius: 5px; display: inline-block; margin-bottom: 15px; }
    .job { border: 1px solid #ddd; padding: 15px; margin: 15px 0; border-radius: 5px; }
    .job-title { color: #3498db; font-size: 18px; font-weight: bold; }
    .company { color: #7f8c8d; font-size: 14px; }
    .score { background: #27ae60; color: white; padding: 5px 10px; border-radius: 3px; display: inline-block; }
    .exp-match { color: #e67e22; font-weight: bold; }
    .details { margin: 10px 0; }
    a { color: #3498db; text-decoration: none; }
  </style>
</head>
<body>
  <h1>🎯 Your Top 5 Job Matches</h1>
  <div class="exp-badge">👤 Your Experience Level: ${expLabel}</div>
  <p>Here are the best job opportunities matched to your experience level and profile:</p>
`;

jobs.forEach((job, index) => {
  html += `
  <div class="job">
    <div class="job-title">${index + 1}. ${job.title}</div>
    <div class="company">${job.company}</div>
    <div class="details">
      <strong>Salary:</strong> ${job.salary}<br>
      <strong>Location:</strong> ${job.location}<br>
      <span class="exp-match">Required Experience:</span> ${job.requiredExperience || "Not specified"}<br>
      <span class="score">Fit Score: ${job.fitScore}%</span>
    </div>
    <p><strong>Why it matches:</strong> ${job.explanation}</p>
    <p><a href="${job.url}" target="_blank">View Job Details →</a></p>
  </div>
  `;
});

html += `
  <p style="margin-top: 30px; color: #7f8c8d; font-size: 12px;">
    This email was generated automatically by your job matching workflow.
  </p>
</body>
</html>
`;

return {
  json: {
    html: html,
    subject: `Your Top ${jobs.length} Job Matches (${expLabel}) - ${new Date().toLocaleDateString()}`
  }
};
